def populate_product_skus_and_approval_status(apps, schema_editor):
    Product = apps.get_model("products", "Product")
    database = schema_editor.connection.alias
    for product in Product.objects.using(database).filter(sku__isnull=True).iterator():
        Product.objects.using(database).filter(pk=product.pk).update(
            sku=f"NG-{product.pk:08d}"
        )
    Product.objects.using(database).filter(is_active=True).update(
        review_status="approved"
    )


